CREATE TABLE public.tasks (id text PRIMARY KEY, subject text NOT NULL, grades text[] NOT NULL, topic text NOT NULL, type text NOT NULL CHECK(type IN ('mc','short','open')), question text NOT NULL, options jsonb NOT NULL DEFAULT '[]', answer text NOT NULL DEFAULT '', explanation text NOT NULL DEFAULT '', steps jsonb NOT NULL DEFAULT '[]', points int NOT NULL DEFAULT 1 CHECK(points > 0), difficulty int NOT NULL DEFAULT 1 CHECK(difficulty BETWEEN 1 AND 3), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.tasks TO authenticated; GRANT ALL ON public.tasks TO service_role;
ALTER TABLE public.tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY tasks_read ON public.tasks FOR SELECT TO authenticated USING(true);
CREATE TRIGGER tasks_updated BEFORE UPDATE ON public.tasks FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TABLE public.attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, task_id text NOT NULL REFERENCES public.tasks(id), correct boolean NOT NULL DEFAULT false, points_earned int NOT NULL DEFAULT 0 CHECK(points_earned >= 0), time_spent_sec int NOT NULL DEFAULT 0 CHECK(time_spent_sec BETWEEN 0 AND 10800), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.attempts TO authenticated; GRANT ALL ON public.attempts TO service_role;
ALTER TABLE public.attempts ENABLE ROW LEVEL SECURITY;
CREATE POLICY attempts_read_own ON public.attempts FOR SELECT TO authenticated USING(auth.uid() = user_id);
CREATE POLICY attempts_insert_own ON public.attempts FOR INSERT TO authenticated WITH CHECK(auth.uid() = user_id);
CREATE INDEX attempts_user_created ON public.attempts(user_id,created_at);
CREATE UNIQUE INDEX attempts_one_success ON public.attempts(user_id,task_id) WHERE correct;
ALTER TABLE public.profiles ADD COLUMN xp int NOT NULL DEFAULT 0, ADD COLUMN streak int NOT NULL DEFAULT 0;
REVOKE INSERT, UPDATE ON public.profiles FROM authenticated;
GRANT INSERT(id,display_name,grade,exams,baseline,goal,struggle,onboarded), UPDATE(display_name,grade,exams,baseline,goal,struggle,onboarded) ON public.profiles TO authenticated;
CREATE FUNCTION public.record_attempt(p_task_id text, p_answer text, p_time_spent_sec int, p_self_points int DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE uid uuid := auth.uid(); t public.tasks; earned int; is_correct boolean; previous_success boolean; a public.attempts; active_streak int;
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF;
 IF p_time_spent_sec IS NULL OR p_time_spent_sec < 0 OR p_time_spent_sec > 10800 OR p_answer IS NULL OR length(trim(p_answer)) = 0 OR length(p_answer)>20000 THEN RAISE EXCEPTION 'Invalid attempt'; END IF;
 PERFORM 1 FROM public.profiles WHERE id=uid FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Profile missing'; END IF;
 SELECT * INTO t FROM public.tasks WHERE id=p_task_id; IF NOT FOUND THEN RAISE EXCEPTION 'Task missing'; END IF;
 SELECT EXISTS(SELECT 1 FROM public.attempts WHERE user_id=uid AND task_id=t.id AND correct) INTO previous_success;
 IF previous_success THEN RAISE EXCEPTION 'Task already solved'; END IF;
 IF t.type='open' THEN
  IF p_self_points IS NULL OR p_self_points < 0 OR p_self_points > t.points THEN RAISE EXCEPTION 'Invalid self assessment'; END IF;
  earned := p_self_points; is_correct := earned=t.points;
 ELSE
  is_correct := lower(regexp_replace(replace(trim(p_answer),',','.'),'\s+',' ','g')) = lower(regexp_replace(replace(trim(t.answer),',','.'),'\s+',' ','g'));
  earned := CASE WHEN is_correct THEN t.points ELSE 0 END;
 END IF;
 INSERT INTO public.attempts(user_id,task_id,correct,points_earned,time_spent_sec) VALUES(uid,t.id,is_correct,earned,p_time_spent_sec) RETURNING * INTO a;
 WITH days AS (SELECT DISTINCT (created_at AT TIME ZONE 'Europe/Riga')::date d FROM public.attempts WHERE user_id=uid), numbered AS (SELECT d, row_number() OVER(ORDER BY d DESC)::int rn FROM days), last_day AS (SELECT max(d) d FROM days)
 SELECT count(*)::int INTO active_streak FROM numbered,last_day WHERE last_day.d >= (now() AT TIME ZONE 'Europe/Riga')::date - 1 AND numbered.d = last_day.d - numbered.rn + 1;
 UPDATE public.profiles SET xp=(SELECT count(*)::int*10 FROM public.attempts WHERE user_id=uid AND correct),streak=active_streak WHERE id=uid;
 RETURN jsonb_build_object('id',a.id,'correct',is_correct,'pointsEarned',earned,'xpEarned',CASE WHEN is_correct THEN 10 ELSE 0 END);
END $$;
REVOKE ALL ON FUNCTION public.record_attempt(text,text,int,int) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.record_attempt(text,text,int,int) TO authenticated;
CREATE FUNCTION public.learning_leaderboard() RETURNS TABLE(name text,xp int,streak int,is_self boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT CASE WHEN p.id=auth.uid() THEN 'Tu' ELSE coalesce(nullif(split_part(trim(p.display_name),' ',1),''),'Skolēns') END,p.xp,p.streak,p.id=auth.uid()
 FROM public.profiles p WHERE auth.uid() IS NOT NULL AND p.onboarded AND (SELECT count(*) FROM public.profiles WHERE onboarded)>=5 ORDER BY p.xp DESC,p.created_at LIMIT 20;
$$;
REVOKE ALL ON FUNCTION public.learning_leaderboard() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.learning_leaderboard() TO authenticated;
